            md += '- **Conclusion**: ' + check.conclusion + '\n';
            if (check.details_url) {
                md += '- **Details**: ' + check.details_url + '\n';
            }
            md += '\n';

            var jobIdMatch = check.details_url && check.details_url.match(/\/jobs?\/(\d+)/);
