                            if (typeof scm.getWorkflowRunJobs === 'function') {
                                rawJobs = scm.getWorkflowRunJobs(runIdMatch[1]);
                            }
                        } else {
                            rawJobs = github_get_workflow_run_jobs({
                                workspace: owner,
                                repository: repo,
                                runId: runIdMatch[1]
                            });
                        }
